mapper.select:
SELECT cohort_id, name, admission_year, term_code, is_active
FROM cohort
WHERE cohort_id = #{cohortId}

SELECT EXISTS(
    SELECT 1 FROM cohort
    WHERE admission_year = #{admissionYear}
      AND term_code = #{termCode}
)

SELECT EXISTS(
    SELECT 1 FROM cohort WHERE name = #{name}
)
